<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\ApiIntegration;
use App\Models\ApiIntegrationEnvironment;
use App\Models\ApiIntegrationLog;
use App\Models\InboundApiKey;
use App\Models\SystemAuditLog;
use App\Services\Integrations\EnvironmentAwareIntegrationService;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
use Inertia\Inertia;
use Inertia\Response;
use Throwable;

class DeveloperToolsController extends Controller
{
    private const ENVIRONMENTS=['development','uat','production'];
    private const SCOPES=[
      'system.read'=>'Check service availability',
      'patients.read'=>'View approved patient information',
      'appointments.read'=>'View appointments and queue status',
      'claims.read'=>'View claims and claim status',
    ];
    private function authorizeView(Request $request): void { abort_unless($request->user()?->can('integrations.view'),403); }
    private function authorizeManage(Request $request): void { abort_unless($request->user()?->can('integrations.manage'),403); }
    private function shared(Request $request): array { return ['canManage'=>$request->user()->can('integrations.manage'),'activeEnvironment'=>app(EnvironmentAwareIntegrationService::class)->environment(),'scopeOptions'=>self::SCOPES,'providers'=>config('integrations.providers',[])]; }
    private function integrationData(): array { return ApiIntegration::query()->with('environments')->orderBy('name')->get()->map(fn($i)=>['id'=>$i->id,'name'=>$i->name,'slug'=>$i->slug,'provider'=>$i->provider,'direction'=>$i->direction,'status'=>$i->status,'environments'=>$i->environments->map(fn($e)=>['id'=>$e->id,'environment'=>$e->environment,'base_url'=>$e->base_url,'token_url'=>$e->token_url,'auth_method'=>$e->auth_method,'client_id'=>$e->client_id,'has_client_secret'=>filled($e->client_secret),'scopes'=>$e->scopes??[],'enabled'=>$e->enabled,'agent_id'=>$e->agent_id,'facility_id'=>$e->facility_id,'facility_id_type'=>$e->facility_id_type,'has_password'=>filled($e->password),'has_consumer_secret'=>filled($e->consumer_secret),'has_private_key'=>filled($e->private_key),'has_public_key'=>filled($e->public_key),'has_provider_public_key'=>filled($e->provider_public_key),'has_client_certificate'=>filled($e->client_certificate),'has_client_certificate_key'=>filled($e->client_certificate_key),'endpoint_map'=>$e->endpoint_map??[],'encrypted_operations'=>$e->encrypted_operations??[],'verify_tls'=>$e->verify_tls])->values()])->values()->all(); }
    private function keyData() { return InboundApiKey::query()->latest()->paginate(25)->through(fn($k)=>['id'=>$k->id,'name'=>$k->name,'prefix'=>$k->prefix,'scopes'=>$k->scopes??[],'environment'=>$k->environment,'expires_at'=>$k->expires_at?->toISOString(),'last_used_at'=>$k->last_used_at?->toISOString(),'revoked_at'=>$k->revoked_at?->toISOString(),'created_at'=>$k->created_at?->toISOString()]); }
    public function index(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/overview',[...$this->shared($request),'integrations'=>$this->integrationData(),'apiKeyCount'=>InboundApiKey::whereNull('revoked_at')->count(),'recentLogs'=>ApiIntegrationLog::query()->latest('created_at')->limit(8)->get()]); }
    public function inboundKeys(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/inbound-keys',[...$this->shared($request),'apiKeys'=>$this->keyData(),'newApiKey'=>$request->session()->pull('newApiKey')]); }
    public function integrations(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/integrations',[...$this->shared($request),'integrations'=>$this->integrationData()]); }
    public function environmentIndex(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/environment-index',[...$this->shared($request),'integrations'=>$this->integrationData()]); }
    public function environments(Request $request, ApiIntegration $integration): Response { $this->authorizeView($request); $integration->load('environments'); return Inertia::render('admin/developer-tools/environments',[...$this->shared($request),'integration'=>$this->integrationDataOne($integration),'environmentOptions'=>self::ENVIRONMENTS]); }
    public function hie(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/hie',[...$this->shared($request),'integrations'=>$this->integrationData(),'officialLinks'=>[
      ['title'=>'DHA HIE developer onboarding','url'=>'https://afyaconnect.dha.go.ke/get-started','description'=>'Register the facility, request API products and obtain environment-specific credentials.'],
      ['title'=>'DHA HIE go-live requirements','url'=>'https://hie-docs.dha.go.ke/docs/goLive','description'=>'Development, mandatory UAT, certification and production go-live.'],
      ['title'=>'AfyaConnect eClaims guide','url'=>'https://afyaconnect.dha.go.ke/docs/eclaims/getting-started/introduction','description'=>'Published eClaims integration guide and authentication details.'],
      ['title'=>'AfyaConnect eligibility API catalogue','url'=>'https://afyaconnect.dha.go.ke/hie-api/eclaims/eligibility','description'=>'Published eligibility and related eClaims API endpoints.'],
      ['title'=>'AfyaLink authentication','url'=>'https://afyalink.dha.go.ke/apidocs/authentication','description'=>'Documented AfyaLink token authentication.'],
      ['title'=>'AfyaLink payload encryption','url'=>'https://afyalink.dha.go.ke/api-authentication-encryption','description'=>'Documented signing and payload encryption requirements.'],
      ['title'=>'SHA EDI Development','url'=>'https://edi-api.provider-dev.sha.go.ke/','description'=>'Official SHA EDI development environment.'],
      ['title'=>'SHA EDI UAT','url'=>'https://edi-api.provider-uat.sha.go.ke/','description'=>'Official SHA EDI UAT environment.'],
      ['title'=>'SHA EDI Production','url'=>'https://api-edi.provider.sha.go.ke/','description'=>'Official SHA EDI production portal.'],
    ]]); }
    public function activity(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/activity',[...$this->shared($request),'logs'=>ApiIntegrationLog::query()->with('integration:id,name,slug')->latest('created_at')->paginate(40)->through(fn($l)=>['id'=>$l->id,'integration'=>$l->integration?->name??'Integration removed','environment'=>$l->environment,'operation'=>$l->operation,'http_status'=>$l->http_status,'result'=>$l->result,'duration_ms'=>$l->duration_ms,'safe_message'=>$l->safe_message,'created_at'=>$l->created_at?->toISOString()])]); }
    public function testing(Request $request): Response { $this->authorizeView($request); return Inertia::render('admin/developer-tools/testing',[...$this->shared($request),'integrations'=>$this->integrationData(),'testResult'=>$request->session()->pull('integrationTestResult')]); }
    public function storeApiKey(Request $request): RedirectResponse { $this->authorizeManage($request); $data=$request->validate(['name'=>['required','string','max:120'],'environment'=>['required',Rule::in(self::ENVIRONMENTS)],'scopes'=>['required','array','min:1'],'scopes.*'=>['required',Rule::in(array_keys(self::SCOPES))],'expires_at'=>['nullable','date','after:now']]); $secret='ivc_'.($data['environment']==='production' ? 'live' : ($data['environment']==='uat' ? 'uat' : 'dev')).'_'.Str::random(48); $key=InboundApiKey::create(['name'=>$data['name'],'prefix'=>substr($secret,0,18),'token_hash'=>hash('sha256',$secret),'scopes'=>array_values(array_unique($data['scopes'])),'environment'=>$data['environment'],'expires_at'=>$data['expires_at']??null,'created_by'=>$request->user()->id]); $this->audit($request,'api_key.created',$key,['name'=>$key->name,'environment'=>$key->environment,'scopes'=>$key->scopes]); return back()->with('newApiKey',['name'=>$key->name,'environment'=>$key->environment,'token'=>$secret]); }
    public function revokeApiKey(Request $request, InboundApiKey $apiKey): RedirectResponse { $this->authorizeManage($request); if($apiKey->revoked_at===null){$apiKey->forceFill(['revoked_at'=>now()])->save();$this->audit($request,'api_key.revoked',$apiKey,['name'=>$apiKey->name,'environment'=>$apiKey->environment]);} return back()->with('success','Partner access key revoked.'); }
    public function storeIntegration(Request $request): RedirectResponse { $this->authorizeManage($request); $data=$request->validate($this->integrationRules()); $data['slug']=Str::slug($data['slug']); $data['updated_by']=$request->user()->id; $i=ApiIntegration::create($data); foreach(self::ENVIRONMENTS as $env) ApiIntegrationEnvironment::firstOrCreate(['api_integration_id'=>$i->id,'environment'=>$env],['auth_method'=>$i->auth_method,'enabled'=>false,'verify_tls'=>true]); $this->audit($request,'api_integration.created',$i,['name'=>$i->name,'slug'=>$i->slug]); return redirect('/developer-tools/integrations/'.$i->id.'/environments')->with('success','Integration created. Configure each environment separately.'); }
    public function updateIntegration(Request $request, ApiIntegration $integration): RedirectResponse { $this->authorizeManage($request); $data=$request->validate($this->integrationRules($integration->id)); if(blank($data['client_secret']??null)) unset($data['client_secret']); $data['slug']=Str::slug($data['slug']); $data['updated_by']=$request->user()->id; $before=$integration->only(['name','slug','provider','direction','status']); $integration->update($data); $this->audit($request,'api_integration.updated',$integration,['before'=>$before,'after'=>$integration->only(['name','slug','provider','direction','status'])]); return back()->with('success','Integration details updated.'); }
    public function deleteIntegration(Request $request, ApiIntegration $integration): RedirectResponse { $this->authorizeManage($request); abort_if(in_array($integration->slug,['sha-edi','dha-hie','dha-afyalink'],true),422,'Official provider profiles cannot be deleted. Disable them instead.'); $snapshot=['name'=>$integration->name,'slug'=>$integration->slug]; $integration->delete(); $this->audit($request,'api_integration.deleted',$integration,$snapshot); return redirect('/developer-tools/integrations')->with('success','Integration deleted.'); }
    public function updateIntegrationStatus(Request $request, ApiIntegration $integration): RedirectResponse { $this->authorizeManage($request); $data=$request->validate(['status'=>['required',Rule::in(['active','inactive'])]]); $integration->update($data); $this->audit($request,'api_integration.status_changed',$integration,['status'=>$data['status']]); return back()->with('success','Integration status updated.'); }
    public function saveEnvironment(Request $request, ApiIntegration $integration): RedirectResponse { $this->authorizeManage($request); $data=$request->validate([
      'environment'=>['required',Rule::in(self::ENVIRONMENTS)],'base_url'=>['nullable','url','max:2048'],'token_url'=>['nullable','url','max:2048'],'auth_method'=>['required',Rule::in(['oauth2_client_credentials','afyalink_configured_bearer','afyalink_signed_jwt','api_key','basic','none'])],'client_id'=>['nullable','string','max:512'],'client_secret'=>['nullable','string','max:8192'],'scopes'=>['nullable','array'],'scopes.*'=>['string','max:255'],'enabled'=>['required','boolean'],'agent_id'=>['nullable','string','max:255'],'facility_id'=>['nullable','string','max:255'],'facility_id_type'=>['nullable','string','max:255'],'username'=>['nullable','string','max:512'],'password'=>['nullable','string','max:4096'],'consumer_key'=>['nullable','string','max:512'],'consumer_secret'=>['nullable','string','max:4096'],'private_key'=>['nullable','string','max:16000'],'public_key'=>['nullable','string','max:16000'],'provider_public_key'=>['nullable','string','max:16000'],'client_certificate'=>['nullable','string','max:16000'],'client_certificate_key'=>['nullable','string','max:16000'],'callback_url'=>['nullable','url','max:2048'],'validation_url'=>['nullable','url','max:2048'],'endpoint_map'=>['nullable','array'],'endpoint_map.*'=>['string','max:2048'],'encrypted_operations'=>['nullable','array'],'encrypted_operations.*'=>['string','max:120'],'verify_tls'=>['required','boolean']]);
      $env=$data['environment']; $existing=ApiIntegrationEnvironment::firstOrNew(['api_integration_id'=>$integration->id,'environment'=>$env]); $secretFields=['client_secret','password','consumer_secret','private_key','client_certificate_key']; foreach($secretFields as $field) if(blank($data[$field]??null)) unset($data[$field]); $data['scopes']=array_values(array_filter($data['scopes']??[])); $data['endpoint_map']=$data['endpoint_map']??[]; $data['encrypted_operations']=$data['encrypted_operations']??[]; if($env!=='development' && ($data['verify_tls']??true)!==true) abort(422,'TLS certificate verification cannot be disabled in UAT or Production.'); if($env!=='development' && filled($data['base_url']??$existing->base_url) && !str_starts_with((string)($data['base_url']??$existing->base_url),'https://')) abort(422,'UAT and Production endpoints must use HTTPS.'); $before=['enabled'=>$existing->enabled,'base_url'=>$existing->base_url,'auth_method'=>$existing->auth_method]; $existing->fill($data); $existing->save(); $this->audit($request,'integration.environment.saved',$existing,['integration'=>$integration->slug,'environment'=>$env,'before'=>$before,'after'=>['enabled'=>$existing->enabled,'base_url'=>$existing->base_url,'auth_method'=>$existing->auth_method,'has_client_secret'=>filled($existing->client_secret)]]); return back()->with('success',strtoupper($env).' settings saved. Secret fields left blank were preserved.'); }
    public function testEnvironment(Request $request, ApiIntegration $integration, EnvironmentAwareIntegrationService $gateway): RedirectResponse { $this->authorizeManage($request); $data=$request->validate(['environment'=>['required',Rule::in(self::ENVIRONMENTS)],'operation'=>['required',Rule::in(['eligibility.check','patient.benefits','patient.benefits.interventions','patient.benefits.utilization','patient.pomsf_balances','patient.sub_benefits','facility.bed_occupancy'])],'parameters'=>['nullable','array'],'parameters.*'=>['nullable','string','max:255']]); $start=microtime(true); try { $result=$gateway->testReadOnlyOperation($integration,$data['environment'],$data['operation'],$data['parameters']??[]); $status=(int)($result['status']??200); $safeMessage=$result['mock']?'Development fixture returned; no external provider was contacted.':($status>=200&&$status<300?'Provider returned a response.':'Provider returned a non-success HTTP response.'); $row=['environment'=>$data['environment'],'operation'=>$data['operation'],'status'=>$status,'mock'=>(bool)($result['mock']??false),'body'=>$result['body']??null,'headers'=>$result['headers']??[],'duration_ms'=>(int)((microtime(true)-$start)*1000)]; ApiIntegrationLog::create(['api_integration_id'=>$integration->id,'user_id'=>$request->user()->id,'environment'=>$data['environment'],'operation'=>$data['operation'],'http_status'=>$status,'result'=>$row['mock']?'mock':($status>=200&&$status<300?'success':'http_error'),'duration_ms'=>$row['duration_ms'],'safe_message'=>$safeMessage]); } catch(Throwable $e) { $row=['environment'=>$data['environment'],'operation'=>$data['operation'],'status'=>null,'mock'=>$data['environment']==='development','error'=>'Request failed: '.Str::limit(preg_replace('/(token|secret|password|authorization)\s*[:=]\s*[^\s,;]+/i','$1=[REDACTED]',$e->getMessage()),300),'duration_ms'=>(int)((microtime(true)-$start)*1000)]; ApiIntegrationLog::create(['api_integration_id'=>$integration->id,'user_id'=>$request->user()->id,'environment'=>$data['environment'],'operation'=>$data['operation'],'http_status'=>null,'result'=>'error','duration_ms'=>$row['duration_ms'],'safe_message'=>$row['error']]); } $this->audit($request,'integration.tested',$integration,['environment'=>$data['environment'],'operation'=>$data['operation'],'status'=>$row['status']??null,'mock'=>$row['mock']??false]); return redirect('/developer-tools/testing')->with('integrationTestResult',['integration'=>$integration->name,...$row]); }
    private function integrationRules(?int $ignoreId=null): array { return ['name'=>['required','string','max:150'],'slug'=>['required','string','max:150',Rule::unique('api_integrations','slug')->ignore($ignoreId)],'provider'=>['required',Rule::in(['custom','dha_hie','sha','other'])],'direction'=>['required',Rule::in(['outbound','bidirectional'])],'base_url'=>['nullable','url','max:2048'],'token_url'=>['nullable','url','max:2048'],'auth_method'=>['required',Rule::in(['oauth2_client_credentials','afyalink_configured_bearer','afyalink_signed_jwt','api_key','basic','none'])],'client_id'=>['nullable','string','max:512'],'client_secret'=>['nullable','string','max:4096'],'scopes'=>['nullable','array'],'scopes.*'=>['string','max:255'],'status'=>['required',Rule::in(['active','inactive'])],'notes'=>['nullable','string','max:5000']]; }
    private function integrationDataOne(ApiIntegration $i): array { return collect($this->integrationData())->firstWhere('id',$i->id); }
    private function audit(Request $request,string $action,$subject,array $after): void { SystemAuditLog::create(['user_id'=>$request->user()->id,'action'=>$action,'subject_type'=>$subject::class,'subject_id'=>$subject->id,'before_values'=>null,'after_values'=>$after,'ip_address'=>$request->ip(),'user_agent'=>substr((string)$request->userAgent(),0,1000),'occurred_at'=>now()]); }
}
